1	import { describe, expect, it } from "vitest";
2	import { can, explain, assertCan, PermissionDeniedError, ROLE_MATRIX } from "@/lib/permissions";
3	import type { Actor, Role } from "@/types/member";
4	import type { OrgId, UserId, IssueId, ProjectId, CommentId } from "@/types/common";
5	import type { PermissionAction, PermissionResource } from "@/types/permission";
6	import {
7	  commentIdSchema,
8	  issueIdSchema,
9	  orgIdSchema,
10	  projectIdSchema,
11	  userIdSchema,
12	} from "@/schemas/common";
13	
14	const ORG = "01HZZZGGGGGGGGGGGGGGGGGGGG" as OrgId;
15	const OTHER_ORG = "01HZZZHHHHHHHHHHHHHHHHHHHH" as OrgId;
16	const ALICE = "01HZZZAAAAAAAAAAAAAAAAAAAA" as UserId;
17	const BOB = "01HZZZBBBBBBBBBBBBBBBBBBBB" as UserId;
18	
19	function actor(role: Role, overrides: Partial<Actor> = {}): Actor {
20	  return { userId: ALICE, orgId: ORG, role, ...overrides };
21	}
22	
23	const orgResource: PermissionResource = { kind: "organization", orgId: ORG };
24	
25	function issueBy(authorId: UserId, assigneeId: UserId | null = null): PermissionResource {
26	  return {
27	    kind: "issue",
28	    orgId: ORG,
29	    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
30	    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
31	    authorId,
32	    assigneeId,
33	  };
34	}
35	
36	function commentBy(authorId: UserId): PermissionResource {
37	  return {
38	    kind: "comment",
39	    orgId: ORG,
40	    commentId: "01HZZZCCCCCCCCCCCCCCCCCCCC" as CommentId,
41	    authorId,
42	  };
43	}
44	
45	describe("can()", () => {
46	  it("grants an action when the actor's role meets the matrix requirement", () => {
47	    expect(can(actor("owner"), "org:delete", orgResource)).toBe(true);
48	    expect(can(actor("admin"), "member:invite", { kind: "organization", orgId: ORG })).toBe(true);
49	    expect(can(actor("viewer"), "issue:read", issueBy(BOB))).toBe(true);
50	  });
51	
52	  it("denies an action below the actor's role rank", () => {
53	    expect(can(actor("admin"), "org:delete", orgResource)).toBe(false);
54	    expect(can(actor("member"), "member:invite", orgResource)).toBe(false);
55	    expect(can(actor("viewer"), "issue:create", issueBy(ALICE))).toBe(false);
56	  });
57	
58	  it("denies every action across a tenant boundary, even for an owner", () => {
59	    const foreign = actor("owner", { orgId: OTHER_ORG });
60	    for (const action of Object.keys(ROLE_MATRIX) as PermissionAction[]) {
61	      expect(can(foreign, action, orgResource)).toBe(false);
62	    }
63	    expect(explain(foreign, "org:read", orgResource).reason).toBe("denied_cross_tenant");
64	  });
65	
66	  it("escalates for ownership: an author may edit their own issue and comment", () => {
67	    const viewer = actor("viewer");
68	    expect(can(viewer, "issue:update", issueBy(ALICE))).toBe(true);
69	    expect(can(viewer, "issue:update", issueBy(BOB))).toBe(false);
70	    expect(can(viewer, "comment:update", commentBy(ALICE))).toBe(true);
71	    expect(can(viewer, "comment:delete", commentBy(BOB))).toBe(false);
72	    expect(explain(viewer, "issue:update", issueBy(ALICE)).reason).toBe(
73	      "granted_by_ownership",
74	    );
75	  });
76	
77	  it("does not escalate ownership for actions outside the escalation list", () => {
78	    expect(can(actor("viewer"), "issue:delete", issueBy(ALICE))).toBe(false);
79	  });
80	
81	  it("lets platform staff bypass the matrix inside the tenant", () => {
82	    const staff = actor("viewer", { isPlatformStaff: true });
83	    expect(can(staff, "org:delete", orgResource)).toBe(true);
84	    expect(explain(staff, "org:delete", orgResource).reason).toBe("granted_by_staff");
85	  });
86	
87	  it("assertCan throws PermissionDeniedError on a denial", () => {
88	    expect(() => assertCan(actor("viewer"), "org:delete", orgResource)).toThrow(
89	      PermissionDeniedError,
90	    );
91	    expect(() => assertCan(actor("owner"), "org:delete", orgResource)).not.toThrow();
92	  });
93	
94	  it("keeps the matrix monotonic: a higher role never loses an action", () => {
95	    const ranks: Role[] = ["viewer", "member", "admin", "owner"];
96	    for (const action of Object.keys(ROLE_MATRIX) as PermissionAction[]) {
97	      let seenAllowed = false;
98	      for (const role of ranks) {
99	        const allowed = can(actor(role), action, orgResource);
100	        if (seenAllowed) expect(allowed).toBe(true);
101	        if (allowed) seenAllowed = true;
102	      }
103	    }
104	  });
105	});
106	
107	describe("fixture ids", () => {
108	  // The ids above are cast with `as`, which skips validation. If a fixture
109	  // drifts outside Crockford base32 (no I, L, O, U) the permission tests keep
110	  // passing while every schema in `src/schemas` would reject the same value —
