 * `createIssue` would be, plus two batch-wide checks: the plan's per-project
 * quota and the workspace's issue-creation rate allowance must both have room
 * for the whole batch before any row is written. A key already imported by
 * this workspace short-circuits to the first import's result instead of
 * writing again.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replay = await issueImportRepo.findImport(input.orgId, input.importKey);
  if (replay) {
    const found = await issueRepo.findIssuesByIds(input.orgId, replay.issueIds);
    const byId = new Map(found.map((issue) => [issue.id, issue]));
    return {
      importKey: input.importKey,
      projectId: replay.projectId,
      issues: replay.issueIds
        .map((id) => byId.get(id))
        .filter((issue): issue is Issue => issue !== undefined),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    "issue:create",
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeIdByEmail = new Map<string, UserId>();
  for (const email of new Set(
    input.rows.flatMap((row) => (row.assigneeEmail === null ? [] : [row.assigneeEmail])),
  )) {
    const member = await memberRepo.findActiveMemberByEmail(input.orgId, email);
    if (member) assigneeIdByEmail.set(email, member.userId);
  }

  const labelIdByName = new Map<string, LabelId>();
  for (const name of new Set(input.rows.flatMap((row) => row.labels))) {
    const existingLabel = await labelRepo.findLabelByName(input.orgId, name);
    const label =
      existingLabel ??
      (await labelRepo.insertLabel({
        orgId: input.orgId,
        name,
        color: IMPORT_LABEL_COLOR,
        description: null,
      }));
    labelIdByName.set(name, label.id);
  }

  const startNumber = await issueRepo.nextIssueNumber(input.orgId, input.projectId);

  const issues: Issue[] = [];
  for (const [index, row] of input.rows.entries()) {
    const labelIds = [...new Set(row.labels)].map(
      (name) => labelIdByName.get(name) as LabelId,
    );

    const issue = await issueRepo.insertIssue(
      {
        orgId: input.orgId,
        projectId: input.projectId,
        title: row.title,
        description: row.description,
        status: row.status,
        priority: row.priority,
        assigneeId:
          row.assigneeEmail === null
            ? null
            : (assigneeIdByEmail.get(row.assigneeEmail) ?? null),
        parentId: null,
        estimate: null,
        dueAt: row.dueAt,
        labelIds,
      },
      actor.userId,
      startNumber + index,
    );
    issues.push(issue);
  }

  const issueIds = issues.map((issue) => issue.id);
  await issueImportRepo.insertImport(
    input.orgId,
    input.importKey,
    input.projectId,
    issueIds,
  );

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds,
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues,
    replayed: false,
  };
}

