/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived, consumeRateLimit
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueImportRepo from "@/server/repositories/issue-import-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { ImportIssuesInput } from "@/schemas/issue-import";
import type { IssueId, LabelId, OrgId, Page, ProjectId, UserId } from "@/types/common";
import type {
  Issue,
  IssueBoardColumn,
  IssueImportResult,
  IssueWithRelations,
} from "@/types/issue";
import type { Actor } from "@/types/member";

/** Default colour a label gets when the importer has to create it. */
const IMPORT_LABEL_COLOR = "#94a3b8";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

/**
 * Bulk-creates every row as an issue, gated the same way a single
 * `createIssue` would be, plus two batch-wide checks: the plan's per-project
 * quota and the workspace's issue-creation rate allowance must both have room
 * for the whole batch before any row is written. A key already imported by
 * this workspace short-circuits to the first import's result instead of
 * writing again.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replay = await issueImportRepo.findImport(input.orgId, input.importKey);
  if (replay) {
    const found = await issueRepo.findIssuesByIds(input.orgId, replay.issueIds);
    const byId = new Map(found.map((issue) => [issue.id, issue]));
    return {
      importKey: input.importKey,
      projectId: replay.projectId,
      issues: replay.issueIds
        .map((id) => byId.get(id))
        .filter((issue): issue is Issue => issue !== undefined),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    "issue:create",
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeIdByEmail = new Map<string, UserId>();
  for (const email of new Set(
    input.rows.flatMap((row) => (row.assigneeEmail === null ? [] : [row.assigneeEmail])),
  )) {
    const member = await memberRepo.findActiveMemberByEmail(input.orgId, email);
    if (member) assigneeIdByEmail.set(email, member.userId);
  }

  const labelIdByName = new Map<string, LabelId>();
  for (const name of new Set(input.rows.flatMap((row) => row.labels))) {
    const existingLabel = await labelRepo.findLabelByName(input.orgId, name);
    const label =
      existingLabel ??
      (await labelRepo.insertLabel({
        orgId: input.orgId,
        name,
        color: IMPORT_LABEL_COLOR,
        description: null,
      }));
    labelIdByName.set(name, label.id);
  }

  const startNumber = await issueRepo.nextIssueNumber(input.orgId, input.projectId);

  const issues: Issue[] = [];
  for (const [index, row] of input.rows.entries()) {
    const labelIds = [...new Set(row.labels)].map(
      (name) => labelIdByName.get(name) as LabelId,
    );

